begin;
set local search_path=public,extensions;
select no_plan();
create temp table cases(name text primary key,value jsonb);
grant all on cases to service_role,authenticated;
create function pg_temp.put(n text,v jsonb) returns void language sql as $$insert into cases values(n,v) on conflict(name) do update set value=excluded.value$$;
create function pg_temp.get(n text) returns jsonb language sql stable as $$select value from cases where name=n$$;
create function pg_temp.actor(n integer) returns uuid language sql immutable as $$select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.failure(statement text) returns text language plpgsql as $$begin execute statement;return 'OK';exception when others then return case when sqlstate='P0001' then sqlerrm else sqlstate end;end$$;
create function pg_temp.session(actor uuid,client text,paper boolean default true) returns uuid language plpgsql as $$declare result jsonb;id uuid;begin
 result:=public.qiyadat_mutate(actor,'start',jsonb_build_object('client_session_id',client,'set_id','7dc73083-f0f1-46a4-ac65-7b7f42a6f9b1',
  'set_version',1,'kind','diagnostic','practice_mode','training','response_mode',case when paper then 'paper' else 'typing' end,'session_size',20),client||'-start-key-0001');
 id:=(result#>>'{body,data,id}')::uuid;perform public.qiyadat_mutate(actor,'finish','{"reason":"manual"}',client||'-finish-key-0001',id);return id;end$$;
create function pg_temp.sid() returns uuid language sql stable as $$select (pg_temp.get('session')#>>'{}')::uuid$$;
create function pg_temp.files(pages integer,size bigint default 100) returns jsonb language sql as $$select jsonb_build_object('files',jsonb_agg(jsonb_build_object(
 'page_number',n,'file_name','page-'||n||'.png','content_type','image/png','size_bytes',size,'sha256',repeat('0',64)) order by n)) from generate_series(1,pages)n$$;
create function pg_temp.body() returns jsonb language sql stable as $$select jsonb_build_object('upload_ids',jsonb_agg(id order by page_number),'language','en') from public.paper_uploads where session_id=pg_temp.sid()$$;
create function pg_temp.jid(n text default 'job') returns uuid language sql stable as $$select (pg_temp.get(n)#>>'{body,data,job_id}')::uuid$$;
create function pg_temp.upload() returns uuid language sql stable as $$select id from public.paper_uploads where session_id=pg_temp.sid() and page_number=1$$;
create function pg_temp.draft() returns jsonb language sql as $$select jsonb_agg(jsonb_build_object('position',n,'ocr_text','OCR draft '||n,'confidence',null,'needs_review',true) order by n) from generate_series(1,20)n$$;
create function pg_temp.confirmation(revision integer) returns jsonb language sql as $$select jsonb_build_object('ocr_revision',revision,'responses',jsonb_agg(jsonb_build_object('position',n,'confirmed_text',case when n=1 then U&'Cafe\0301' else '' end) order by n)) from generate_series(1,20)n$$;
create function pg_temp.complete_pages(job uuid,worker uuid) returns void language plpgsql as $$declare u uuid;begin
 for u in select upload_id from private.ocr_job_pages where job_id=job order by ordinal loop
  perform public.qiyadat_ocr_page_event(job,worker,u,'dispatch');perform public.qiyadat_ocr_page_event(job,worker,u,'accepted');
  perform public.qiyadat_ocr_page_event(job,worker,u,'done','[{"text":"OCR draft","confidence":null}]');
 end loop;end$$;
grant execute on all functions in schema pg_temp to service_role,authenticated;
insert into auth.users(id,email) select pg_temp.actor(n),'paper-'||n||'@example.invalid' from generate_series(501,508)n;
-- Isolate provider counters inside this rollback transaction; HTTP mock runs
-- intentionally leave their global safety counts in place after user cleanup.
delete from private.ocr_provider_windows;
select ok(not has_function_privilege('anon','qiyadat_paper_prepare(uuid,uuid,jsonb)','EXECUTE'),'Anonymous cannot prepare');
select ok(not has_function_privilege('authenticated','qiyadat_paper_request_ocr(uuid,uuid,jsonb,text)','EXECUTE'),'Browser cannot forge OCR reservations');
select ok(not has_function_privilege('authenticated','qiyadat_ocr_claim(uuid)','EXECUTE'),'Browser cannot claim');
select ok(not has_function_privilege('authenticated','qiyadat_ocr_complete(uuid,uuid,jsonb)','EXECUTE'),'Browser cannot forge OCR output');
select ok(not has_function_privilege('authenticated','qiyadat_paper_confirm(uuid,uuid,jsonb)','EXECUTE'),'Browser cannot forge confirmation actor');
select ok(not has_table_privilege('authenticated','private.ocr_job_pages','SELECT'),'Page processing cache is private');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='private.ocr_job_pages'::regclass),'Page cache has forced RLS');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.put('session',to_jsonb(pg_temp.session(pg_temp.actor(501),'phase4-paper')));
select is(pg_temp.failure($q$select qiyadat_paper_prepare(pg_temp.actor(502),pg_temp.sid(),pg_temp.files(2))$q$),'NOT_FOUND','Foreign prepare hidden');
select is(pg_temp.failure($q$select qiyadat_paper_prepare(pg_temp.actor(501),pg_temp.sid(),pg_temp.files(2))$q$),'FEATURE_DISABLED','OCR seed disabled');
update app_settings set value='true' where key='ocr_enabled';
select pg_temp.put('typed',to_jsonb(pg_temp.session(pg_temp.actor(502),'phase4-typed',false)));
select is(pg_temp.failure($q$select qiyadat_paper_prepare(pg_temp.actor(502),(pg_temp.get('typed')#>>'{}')::uuid,pg_temp.files(1))$q$),'SESSION_STATE_CONFLICT','Typed session rejected');
select is(pg_temp.failure($q$select qiyadat_paper_prepare(pg_temp.actor(501),pg_temp.sid(),pg_temp.files(5))$q$),'PAPER_UPLOAD_INCOMPLETE','Five pages rejected');
select is(pg_temp.failure($q$select qiyadat_paper_prepare(pg_temp.actor(501),pg_temp.sid(),jsonb_set(pg_temp.files(2),'{files,1,page_number}','1'))$q$),'PAPER_UPLOAD_INCOMPLETE','Duplicate page rejected');
select is(pg_temp.failure($q$select qiyadat_paper_prepare(pg_temp.actor(501),pg_temp.sid(),jsonb_set(pg_temp.files(2),'{files,0,page_number}','2'))$q$),'PAPER_UPLOAD_INCOMPLETE','Ordering must start at one');
select is(pg_temp.failure($q$select qiyadat_paper_prepare(pg_temp.actor(501),pg_temp.sid(),pg_temp.files(1,8388609))$q$),'UPLOAD_TOO_LARGE','Per-image bound');
select is(pg_temp.failure($q$select qiyadat_paper_prepare(pg_temp.actor(501),pg_temp.sid(),pg_temp.files(4,8388608))$q$),'UPLOAD_TOO_LARGE','Combined bound');
select is(pg_temp.failure($q$select qiyadat_paper_prepare(pg_temp.actor(501),pg_temp.sid(),jsonb_set(pg_temp.files(1),'{files,0,content_type}','"application/pdf"'))$q$),'UNSUPPORTED_MEDIA_TYPE','PDF rejected');
select is(pg_temp.failure($q$select qiyadat_paper_prepare(pg_temp.actor(501),pg_temp.sid(),jsonb_set(pg_temp.files(1),'{files,0,sha256}',to_jsonb(repeat('A',64))))$q$),'VALIDATION_ERROR','Lowercase checksum required');
select is(pg_temp.failure($q$select qiyadat_paper_prepare(pg_temp.actor(501),pg_temp.sid(),jsonb_set(pg_temp.files(1),'{files,0,file_name}','"../page.png"'))$q$),'VALIDATION_ERROR','Traversal filename rejected');
select pg_temp.put('prepared',qiyadat_paper_prepare(pg_temp.actor(501),pg_temp.sid(),pg_temp.files(2)));
select is(jsonb_array_length(pg_temp.get('prepared')->'uploads'),2,'Two authorizations');
select is((select count(*)::integer from paper_uploads where object_path like 'paper-pages/%'),2,'Only controlled paths');
select ok((select bool_and(upload_expires_at=created_at+interval '900 seconds') from paper_uploads),'Exact 900-second authorization');
select ok((select bool_and(expires_at=created_at+interval '24 hours') from paper_uploads),'24-hour abandonment limit');
select is(qiyadat_paper_prepare(pg_temp.actor(501),pg_temp.sid(),pg_temp.files(2)),pg_temp.get('prepared'),'Repeated preparation reuses rows');
select is(pg_temp.failure($q$select qiyadat_paper_prepare(pg_temp.actor(501),pg_temp.sid(),pg_temp.files(3))$q$),'SESSION_STATE_CONFLICT','Repeat cannot append pages');
select is(pg_temp.failure($q$select qiyadat_paper_ocr_context(pg_temp.actor(501),pg_temp.sid(),pg_temp.body(),'phase4-missing-upload-key')$q$),'PAPER_UPLOAD_INCOMPLETE','Must upload every prepared page');
select pg_temp.put('claim',qiyadat_paper_upload_context(pg_temp.actor(501),pg_temp.sid(),pg_temp.upload(),pg_temp.actor(599)));
select is(pg_temp.failure($q$select qiyadat_paper_upload_context(pg_temp.actor(501),pg_temp.sid(),pg_temp.upload(),pg_temp.actor(598))$q$),'SESSION_STATE_CONFLICT','Upload lease fences duplicates');
select ok(not qiyadat_paper_upload_complete(pg_temp.actor(501),pg_temp.sid(),pg_temp.upload(),pg_temp.actor(598),true),'Foreign upload lease cannot commit');
select ok(qiyadat_paper_upload_complete(pg_temp.actor(501),pg_temp.sid(),pg_temp.upload(),pg_temp.actor(599),true),'Correct upload lease commits');
select qiyadat_paper_upload_context(pg_temp.actor(501),pg_temp.sid(),id,pg_temp.actor(599)) from paper_uploads where page_number=2;
select qiyadat_paper_upload_complete(pg_temp.actor(501),pg_temp.sid(),id,pg_temp.actor(599),true) from paper_uploads where page_number=2;
select is(pg_temp.failure($q$select qiyadat_paper_ocr_context(pg_temp.actor(501),pg_temp.sid(),jsonb_set(pg_temp.body(),'{upload_ids,1}',pg_temp.body()#>'{upload_ids,0}'),'phase4-duplicate-upload-key')$q$),'PAPER_UPLOAD_INCOMPLETE','Duplicate upload ID rejected');
select is(pg_temp.failure($q$select qiyadat_paper_ocr_context(pg_temp.actor(501),pg_temp.sid(),jsonb_set(pg_temp.body(),'{upload_ids}',(pg_temp.body()->'upload_ids')-1),'phase4-missing-page-key')$q$),'PAPER_UPLOAD_INCOMPLETE','Missing page rejected');
select pg_temp.put('capjob',to_jsonb(gen_random_uuid()));
insert into processing_jobs(id,user_id,session_id,type,max_attempts) values((pg_temp.get('capjob')#>>'{}')::uuid,pg_temp.actor(501),pg_temp.sid(),'export',1);
insert into usage_reservations(user_id,session_id,job_id,type,operation_key)
 select pg_temp.actor(501),pg_temp.sid(),(pg_temp.get('capjob')#>>'{}')::uuid,'ocr_page','cap-fixture-'||n from generate_series(1,899)n;
select is(pg_temp.failure($q$select qiyadat_paper_request_ocr(pg_temp.actor(501),pg_temp.sid(),pg_temp.body(),'phase4-full-month-cap-key')$q$),'GLOBAL_QUOTA_EXHAUSTED','899 plus two exceeds monthly 900 pages');
delete from usage_reservations where operation_key='cap-fixture-899';
select pg_temp.put('job',qiyadat_paper_request_ocr(pg_temp.actor(501),pg_temp.sid(),pg_temp.body(),'phase4-ocr-request-key'));
select is((select count(*)::integer from usage_reservations where type='ocr_page'),900,'Exactly 900 reserved monthly pages accepted');
delete from processing_jobs where id=(pg_temp.get('capjob')#>>'{}')::uuid;
select is((select status::text from wat_sessions where id=pg_temp.sid()),'ocr_queued','Session queued atomically');
select is((select count(*)::integer from usage_reservations where type='ocr_page'),2,'One unit per page, no report quota');
select is(qiyadat_paper_request_ocr(pg_temp.actor(501),pg_temp.sid(),pg_temp.body(),'phase4-ocr-request-key'),pg_temp.get('job'),'Idempotency exact replay');
select is((select count(*)::integer from usage_reservations),2,'Replay does not double reserve');
select is(pg_temp.failure($q$select qiyadat_paper_request_ocr(pg_temp.actor(501),pg_temp.sid(),jsonb_set(pg_temp.body(),'{language}','"ur"'),'phase4-ocr-request-key')$q$),'IDEMPOTENCY_CONFLICT','Changed input conflict precedes validation');
select is(pg_temp.failure($q$select qiyadat_paper_request_ocr(pg_temp.actor(501),pg_temp.sid(),pg_temp.body(),'phase4-second-live-job-key')$q$),'SESSION_STATE_CONFLICT','One active job per session');
select pg_temp.put('worker',qiyadat_ocr_claim(pg_temp.actor(599)));
select is(pg_temp.get('worker')->>'attempt','1','Claim increments attempt');
select is((select status::text from wat_sessions where id=pg_temp.sid()),'ocr_processing','Claim advances session');
select ok(qiyadat_ocr_claim(pg_temp.actor(598)) is null,'Second worker cannot claim processing job');
select is(pg_temp.failure($q$select qiyadat_ocr_page_event(pg_temp.jid(),pg_temp.actor(598),pg_temp.upload(),'dispatch')$q$),'SESSION_STATE_CONFLICT','Stale worker fenced');
update processing_jobs set locked_at=statement_timestamp()-interval '6 minutes' where id=pg_temp.jid();
select is(qiyadat_ocr_recover(),1,'Stale lease recovered');
select is((select status::text from processing_jobs where id=pg_temp.jid()),'retrying','Stale work retryable');
select ok((select locked_by is null and locked_at is null from processing_jobs where id=pg_temp.jid()),'Recovery releases lock');
update processing_jobs set next_attempt_at=statement_timestamp() where id=pg_temp.jid();
select qiyadat_ocr_claim(pg_temp.actor(599));
select pg_temp.complete_pages(pg_temp.jid(),pg_temp.actor(599));
select is((select hits from private.ocr_provider_windows),2,'Two actual page dispatches counted separately from logical quota');
select qiyadat_ocr_page_event(pg_temp.jid(),pg_temp.actor(599),pg_temp.upload(),'dispatch');
select is((select hits from private.ocr_provider_windows),2,'Dispatch acknowledgement replay does not double count');
select is((select count(*)::integer from usage_reservations where status='consumed'),2,'Accepted provider requests consume pages once');
select qiyadat_ocr_page_event(pg_temp.jid(),pg_temp.actor(599),pg_temp.upload(),'accepted');
select is((select count(*)::integer from usage_reservations where status='consumed'),2,'Accepted acknowledgement replay does not recount');
select is(qiyadat_ocr_complete(pg_temp.jid(),pg_temp.actor(599),pg_temp.draft()),1,'Successful revision one');
select is((select count(*)::integer from ocr_drafts),20,'Twenty draft rows');
select is((select status::text from wat_sessions where id=pg_temp.sid()),'awaiting_confirmation','Mandatory review state');
select is(qiyadat_ocr_complete(pg_temp.jid(),pg_temp.actor(599),pg_temp.draft()),1,'Completion acknowledgement replay safe');
select is(qiyadat_job_read(pg_temp.actor(501),pg_temp.jid())#>>'{result,next_action}','confirm_ocr','Job has safe next action');
select is(pg_temp.failure($q$select qiyadat_job_read(pg_temp.actor(502),pg_temp.jid())$q$),'NOT_FOUND','Foreign job hidden');
select is(pg_temp.failure($q$select qiyadat_request_report(pg_temp.actor(501),pg_temp.sid(),'{"rubric_version":"wat-rubric-v1"}','phase4-before-confirm-key')$q$),'SESSION_STATE_CONFLICT','Unconfirmed text never generates feedback');
select pg_temp.put('job2',qiyadat_paper_request_ocr(pg_temp.actor(501),pg_temp.sid(),pg_temp.body(),'phase4-ocr-rerun-key'));
select qiyadat_ocr_claim(pg_temp.actor(599));
select pg_temp.complete_pages(pg_temp.jid('job2'),pg_temp.actor(599));
select is(qiyadat_ocr_complete(pg_temp.jid('job2'),pg_temp.actor(599),pg_temp.draft()),2,'Rerun increments revision');
select is((select hits from private.ocr_provider_windows),4,'Explicit OCR rerun counts new provider page requests');
select is(qiyadat_job_read(pg_temp.actor(501),pg_temp.jid())#>>'{result,ocr_revision}','1','Previous job keeps its own revision');
select is(pg_temp.failure($q$select qiyadat_paper_confirm(pg_temp.actor(501),pg_temp.sid(),pg_temp.confirmation(1))$q$),'OCR_CONFIRMATION_STALE','Stale revision rejected');
select is(pg_temp.failure($q$select qiyadat_paper_confirm(pg_temp.actor(502),pg_temp.sid(),pg_temp.confirmation(2))$q$),'NOT_FOUND','Foreign confirmation hidden');
select is(pg_temp.failure($q$select qiyadat_paper_confirm(pg_temp.actor(501),pg_temp.sid(),jsonb_set(pg_temp.confirmation(2),'{responses}',(pg_temp.confirmation(2)->'responses')-19))$q$),'OCR_TEXT_INCOMPLETE','Every confirmation position required');
select is(pg_temp.failure($q$select qiyadat_paper_confirm(pg_temp.actor(501),pg_temp.sid(),jsonb_set(pg_temp.confirmation(2),'{responses,19,position}','1'))$q$),'OCR_TEXT_INCOMPLETE','Duplicate confirmation rejected atomically');
select is((select count(*)::integer from wat_responses where session_id=pg_temp.sid() and locked),0,'Invalid confirmation rolled back');
select is(pg_temp.failure($q$select qiyadat_paper_confirm(pg_temp.actor(501),pg_temp.sid(),jsonb_set(pg_temp.confirmation(2),'{responses,0,confirmed_text}',to_jsonb(repeat('x',281))))$q$),'VALIDATION_ERROR','281 code points rejected');
reset role;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.actor(501))::text,true);
select is(jsonb_array_length(qiyadat_paper_draft(pg_temp.sid())->'responses'),20,'Owner draft has exactly twenty rows');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.actor(502))::text,true);
select is(pg_temp.failure($q$select qiyadat_paper_draft(pg_temp.sid())$q$),'NOT_FOUND','Cross-user draft hidden by RLS');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.put('confirmation',qiyadat_paper_confirm(pg_temp.actor(501),pg_temp.sid(),pg_temp.confirmation(2)));
select is((select status::text from wat_sessions where id=pg_temp.sid()),'finished','Confirmation returns to finished');
select is((select count(*)::integer from wat_responses where session_id=pg_temp.sid() and locked and source='ocr_confirmed'),20,'Twenty canonical locked OCR-confirmed responses');
select is((select answer from wat_responses where session_id=pg_temp.sid() and position=1),U&'Caf\00e9','NFC normalization preserves capitalization');
select is((select count(*)::integer from wat_responses where session_id=pg_temp.sid() and status='blank'),19,'Blank confirmation allowed');
select is((select count(*)::integer from ocr_drafts),0,'Draft text deleted atomically');
select is((select count(*)::integer from private.ocr_job_pages),0,'Transient page text deleted');
select is((select count(*)::integer from paper_uploads where status='delete_pending'),2,'Images immediately marked for deletion');
select is(pg_temp.get('confirmation')#>>'{images,status}','delete_pending','Safe fallback deletion response');
select is(jsonb_array_length(qiyadat_paper_cleanup_candidates(pg_temp.sid())),2,'Cleanup selects exact pending keys');
select ok(qiyadat_paper_deleted(id),'Absent object metadata can be marked deleted') from paper_uploads;
select is(jsonb_array_length(qiyadat_paper_cleanup_candidates(pg_temp.sid())),0,'Cleanup idempotent, deleted rows do not starve new work');
update app_settings set value='true' where key='feedback_enabled';
insert into profile_consents(user_id,terms_version,accepted) values(pg_temp.actor(501),'2026-10-01',true);
select is(qiyadat_request_report(pg_temp.actor(501),pg_temp.sid(),'{"rubric_version":"wat-rubric-v1"}','phase4-confirmed-report-key')->>'status','202','Existing report pipeline accepts confirmed paper');
select is((select count(*)::integer from usage_reservations where type='diagnostic_report'),1,'OCR did not consume report allowance');
select pg_temp.put('main',pg_temp.get('session'));
select pg_temp.put('session',to_jsonb(pg_temp.session(pg_temp.actor(503),'phase4-expired')));
insert into paper_uploads(id,user_id,session_id,page_number,content_type,size_bytes,sha256,object_path,created_at,updated_at,upload_expires_at,expires_at)
 values(pg_temp.actor(530),pg_temp.actor(503),pg_temp.sid(),1,'image/png',100,repeat('0',64),'paper-pages/'||pg_temp.actor(503)||'/'||pg_temp.sid()||'/'||pg_temp.actor(530)||'.png',
 statement_timestamp()-interval '1 hour',statement_timestamp(),statement_timestamp()-interval '45 minutes',statement_timestamp()+interval '23 hours');
select is(pg_temp.failure($q$select qiyadat_paper_upload_context(pg_temp.actor(503),pg_temp.sid(),pg_temp.upload())$q$),'UPLOAD_EXPIRED','Expired authorization rejects relay context');
select is(pg_temp.failure($q$select qiyadat_paper_ocr_context(pg_temp.actor(503),pg_temp.sid(),pg_temp.body(),'phase4-expired-ocr-key')$q$),'UPLOAD_EXPIRED','Expired prepared upload cannot enter OCR');
select is(jsonb_array_length(qiyadat_paper_cleanup_candidates(pg_temp.sid())),1,'Expired prepared authorization is cleaned');
select ok(qiyadat_paper_deleted(pg_temp.upload()),'Expired absent object deletion is idempotent');
select pg_temp.put('session',to_jsonb(pg_temp.session(pg_temp.actor(504),'phase4-kill-switch')));
select qiyadat_paper_prepare(pg_temp.actor(504),pg_temp.sid(),pg_temp.files(1));
select qiyadat_paper_upload_context(pg_temp.actor(504),pg_temp.sid(),pg_temp.upload(),pg_temp.actor(599));
select qiyadat_paper_upload_complete(pg_temp.actor(504),pg_temp.sid(),pg_temp.upload(),pg_temp.actor(599),true);
select pg_temp.put('disabledjob',qiyadat_paper_request_ocr(pg_temp.actor(504),pg_temp.sid(),pg_temp.body(),'phase4-kill-switch-ocr-key'));
update app_settings set value='false' where key='ocr_enabled';
select ok(qiyadat_ocr_claim(pg_temp.actor(599)) is null,'Kill switch prevents dispatch');
select is((select status::text from processing_jobs where id=pg_temp.jid('disabledjob')),'failed','Disabled work terminates safely');
select is((select error_code from processing_jobs where id=pg_temp.jid('disabledjob')),'FEATURE_DISABLED','Safe kill-switch error');
select is((select status::text from usage_reservations where job_id=pg_temp.jid('disabledjob')),'released','Never-dispatched page quota released');
update app_settings set value='true' where key='ocr_enabled';
select pg_temp.put('retriedjob',qiyadat_paper_request_ocr(pg_temp.actor(504),pg_temp.sid(),pg_temp.body(),'phase4-technical-retry-key'));
select is((select count(*)::integer from wat_sessions where user_id=pg_temp.actor(504) and is_free_demo),1,'OCR recovery never grants a second demo');
select qiyadat_ocr_claim(pg_temp.actor(599));
select qiyadat_ocr_fail(pg_temp.jid('retriedjob'),pg_temp.actor(599),'OCR_FAILED',false);
select is((select status::text from processing_jobs where id=pg_temp.jid('retriedjob')),'failed','Invalid OCR terminal, not retried');
select pg_temp.put('session',to_jsonb(pg_temp.session(pg_temp.actor(505),'phase4-attempts')));
select qiyadat_paper_prepare(pg_temp.actor(505),pg_temp.sid(),pg_temp.files(1));
select qiyadat_paper_upload_context(pg_temp.actor(505),pg_temp.sid(),pg_temp.upload(),pg_temp.actor(599));
select qiyadat_paper_upload_complete(pg_temp.actor(505),pg_temp.sid(),pg_temp.upload(),pg_temp.actor(599),true);
select pg_temp.put('boundedjob',qiyadat_paper_request_ocr(pg_temp.actor(505),pg_temp.sid(),pg_temp.body(),'phase4-attempt-limit-key'));
select qiyadat_ocr_claim(pg_temp.actor(599));
select qiyadat_ocr_fail(pg_temp.jid('boundedjob'),pg_temp.actor(599),'PROVIDER_UNAVAILABLE',true);
select is((select status::text from processing_jobs where id=pg_temp.jid('boundedjob')),'retrying','First transient failure retries');
update processing_jobs set next_attempt_at=statement_timestamp() where id=pg_temp.jid('boundedjob');
select qiyadat_ocr_claim(pg_temp.actor(599));
select qiyadat_ocr_fail(pg_temp.jid('boundedjob'),pg_temp.actor(599),'PROVIDER_UNAVAILABLE',true);
select is((select status::text from processing_jobs where id=pg_temp.jid('boundedjob')),'retrying','Second transient failure retries');
update processing_jobs set next_attempt_at=statement_timestamp() where id=pg_temp.jid('boundedjob');
select qiyadat_ocr_claim(pg_temp.actor(599));
select qiyadat_ocr_fail(pg_temp.jid('boundedjob'),pg_temp.actor(599),'PROVIDER_UNAVAILABLE',true);
select is((select attempt from processing_jobs where id=pg_temp.jid('boundedjob')),3,'Maximum OCR attempts is three');
select is((select status::text from processing_jobs where id=pg_temp.jid('boundedjob')),'failed','Third failure terminal');
select ok((select locked_at is null and locked_by is null from processing_jobs where id=pg_temp.jid('boundedjob')),'Terminal failure releases lease');
select is((select status::text from usage_reservations where job_id=pg_temp.jid('boundedjob')),'released','Never-dispatched terminal quota released');
select is(qiyadat_paper_prepare(pg_temp.actor(505),pg_temp.sid(),pg_temp.files(1))->>'recovering','true','Retake first requests deletion of previous images');
select qiyadat_paper_cleanup_candidates(pg_temp.sid());
select qiyadat_paper_deleted(pg_temp.upload());
select qiyadat_paper_prepare(pg_temp.actor(505),pg_temp.sid(),pg_temp.files(1));
select is((select status::text from wat_sessions where id=pg_temp.sid()),'awaiting_upload','Trusted retake restores same session after deletion');
select is((select count(*)::integer from wat_sessions where user_id=pg_temp.actor(505) and is_free_demo),1,'Retake does not reset lifetime claim');
select pg_temp.put('session',to_jsonb(pg_temp.session(pg_temp.actor(506),'phase4-abandoned')));
insert into paper_uploads(id,user_id,session_id,page_number,content_type,size_bytes,sha256,object_path,status,created_at,updated_at,upload_expires_at,expires_at,uploaded_at)
 values(pg_temp.actor(531),pg_temp.actor(506),pg_temp.sid(),1,'image/png',100,repeat('0',64),'paper-pages/'||pg_temp.actor(506)||'/'||pg_temp.sid()||'/'||pg_temp.actor(531)||'.png','uploaded',
 statement_timestamp()-interval '25 hours',statement_timestamp(),statement_timestamp()-interval '24 hours 45 minutes',statement_timestamp()-interval '1 hour',statement_timestamp()-interval '24 hours 59 minutes');
insert into ocr_drafts(session_id,user_id,ocr_revision,position,ocr_text,created_at,updated_at,expires_at)
 values(pg_temp.sid(),pg_temp.actor(506),1,1,'Transient expired text',statement_timestamp()-interval '25 hours',statement_timestamp(),statement_timestamp()-interval '1 hour');
select is(jsonb_array_length(qiyadat_paper_cleanup_candidates(pg_temp.sid())),1,'24-hour abandoned object selected');
select is((select count(*)::integer from ocr_drafts where session_id=pg_temp.sid()),0,'Expired OCR draft is removed');
select ok((select answer<>'' from wat_responses where session_id=(pg_temp.get('main')#>>'{}')::uuid and position=1),'Cleanup preserves confirmed text');
insert into storage.objects(bucket_id,name,created_at) values('paper-uploads','paper-pages/'||pg_temp.actor(506)||'/'||pg_temp.sid()||'/'||pg_temp.actor(532)||'.png',statement_timestamp()-interval '20 minutes');
select ok(exists(select 1 from jsonb_array_elements(qiyadat_paper_cleanup_candidates()) e where e->'id'='null'::jsonb and e->>'object_path' like '%'||pg_temp.actor(532)||'.png'),'Cleanup enumerates controlled orphan keys');
select pg_temp.put('session',to_jsonb(pg_temp.session(pg_temp.actor(507),'phase4-three-pages')));
select is(jsonb_array_length(qiyadat_paper_prepare(pg_temp.actor(507),pg_temp.sid(),pg_temp.files(3))->'uploads'),3,'Three contiguous pages accepted');
select pg_temp.put('session',to_jsonb(pg_temp.session(pg_temp.actor(508),'phase4-four-pages')));
select is(jsonb_array_length(qiyadat_paper_prepare(pg_temp.actor(508),pg_temp.sid(),pg_temp.files(4,6291456))->'uploads'),4,'Four pages at exact combined 24 MiB accepted');
select * from finish();
rollback;
